import unittest
from producer import emit


class ProducerTests(unittest.TestCase):
    def test_valid_events_emit_only_successes(self):
        for event in ('opened', 'body', 'restored'):
            self.assertTrue(all(value == 'success' for value in emit(event, True).values()))

    def test_invalid_title_fails(self):
        self.assertEqual(emit('invalid', False)['title'], 'failure')

